// ujwalam-host: device gating (flag off; devices.list too, D38) and project v1 load (A's model) on a real host.
//   node --test app/host/tests/
// No device is opened or listed: the host runs without --allow-devices. Media and image files are generated by ffmpeg into out/ (gitignored).
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { launchHost, stopHost } from '../lib/launch.mjs';
import { loadIntoHost, planInHost, ProjectRefused } from '../lib/project.mjs';
import { REPO_ROOT, HOST_DIR } from '../lib/config.mjs';

const OUT = path.join(REPO_ROOT, 'out', 'host', 'tests');
const SAMPLE = JSON.parse(readFileSync(path.join(REPO_ROOT, 'tests', 'fixtures', 'project', 'sample.project.json'), 'utf8'));
const clone = (x) => JSON.parse(JSON.stringify(x));
let h;
let c;
let media;

function ffmpeg(args) {
  const r = spawnSync(process.env.FFMPEG || 'ffmpeg', ['-hide_banner', '-loglevel', 'error', '-y', ...args], { encoding: 'utf8', windowsHide: true });
  assert.equal(r.status, 0, r.stderr);
}

before(async () => {
  mkdirSync(OUT, { recursive: true });
  media = mkdtempSync(path.join(OUT, 'media-'));
  ffmpeg(['-f', 'lavfi', '-i', 'color=c=blue:s=64x64', '-frames:v', '1', path.join(media, 'logo.png')]);
  ffmpeg(['-f', 'lavfi', '-i', 'testsrc2=size=320x240:rate=30', '-f', 'lavfi', '-i', 'sine=frequency=440:sample_rate=48000',
    '-t', '3', '-c:v', 'mpeg4', '-q:v', '5', '-c:a', 'aac', '-shortest', path.join(media, 'intro.mp4')]);
  h = await launchHost({ dataDir: mkdtempSync(path.join(OUT, 'data-')), project: path.join(HOST_DIR, 'projects', 'test-card.project.json') });
  c = h.client;
});

after(async () => {
  if (!h) return;
  const r = await stopHost(h);
  assert.equal(r.code, 0, 'host exits 0');
});

async function rpcErr(method, params) {
  try {
    await c.call(method, params);
  } catch (e) {
    return e;
  }
  assert.fail(`${method} should have failed`);
}

// Windows privacy store: an app that opens a camera or microphone gets (or updates) a subkey here, named after its
// exe path with "\" as "#". Read-only query.
function consentSnapshot() {
  const exeKey = h.cfg.exe.replaceAll('\\', '#').replaceAll('/', '#').toLowerCase();
  const snap = {};
  for (const cap of ['webcam', 'microphone']) {
    const key = `HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\CapabilityAccessManager\\ConsentStore\\${cap}\\NonPackaged`;
    const r = spawnSync('reg', ['query', key, '/s'], { encoding: 'utf8', windowsHide: true });
    const blocks = {};
    let cur = null;
    for (const line of (r.stdout || '').split(/\r?\n/)) {
      if (line.startsWith('HKEY_')) { cur = line.trim().toLowerCase(); blocks[cur] = []; } else if (cur && line.trim()) blocks[cur].push(line.trim());
    }
    const mine = Object.entries(blocks).filter(([k]) => k.endsWith(exeKey));
    const hostAny = Object.entries(blocks).filter(([k]) => k.includes('ujwalam-host'));
    snap[cap] = { status: r.status, keys: Object.keys(blocks).length, mine: JSON.stringify(mine), hostAny: JSON.stringify(hostAny) };
  }
  return snap;
}

function tasklistHas(pid, dll) {
  const r = spawnSync('tasklist', ['/m', dll, '/fi', `PID eq ${pid}`, '/fo', 'csv', '/nh'], { encoding: 'utf8', windowsHide: true });
  assert.equal(r.status, 0, r.stderr);
  return r.stdout.includes(`"${pid}"`);
}

test('browser off: no overlay server, effect.fire refused, overlay layers forbidden', async () => {
  const st = await c.call('overlay.status');
  assert.equal(st.state, 'off');
  assert.equal(st.browserAllowed, false);
  assert.equal((await c.call('host.info')).overlay, null);
  assert.equal((await rpcErr('effect.fire', { name: 'gg' })).code, -32001);
  assert.equal((await rpcErr('overlay.stats', {})).code, -32004, 'overlay.stats: unavailable while the server is off');
  const plan = await planInHost(c, SAMPLE, { bases: { media, overlays: media } });
  const chat = plan.unavailable.find((u) => u.layer === 'layer-chat');
  assert.equal(chat.code, 'forbidden');
  assert.match(chat.reason, /--allow-browser/);
});

test('flag off: no device module is loaded and no device source type exists', async () => {
  const info = await c.call('host.info');
  assert.equal(info.flags.allowDevices, false);
  assert.deepEqual(info.deviceModules, { 'win-dshow.dll': false, 'win-wasapi.dll': false });
  for (const t of ['dshow_input', 'wasapi_input_capture', 'wasapi_output_capture', 'wasapi_process_output_capture'])
    assert.ok(!info.sourceTypes.includes(t), `${t} not registered`);
  assert.ok(info.sourceTypes.includes('ffmpeg_source') && info.sourceTypes.includes('color_source_v3'), 'non-device sources load');
  // independent of the host's own report
  assert.equal(tasklistHas(h.child.pid, 'win-dshow.dll'), false, 'tasklist: win-dshow.dll not mapped');
  assert.equal(tasklistHas(h.child.pid, 'win-wasapi.dll'), false, 'tasklist: win-wasapi.dll not mapped');
  assert.equal(tasklistHas(h.child.pid, 'obs.dll'), true, 'tasklist control: obs.dll is mapped');
});

test('devices.list is refused without --allow-devices; nothing is listed or opened', async () => {
  const before0 = consentSnapshot();
  assert.equal((await rpcErr('devices.list')).code, -32001);
  const after0 = consentSnapshot();
  for (const cap of ['webcam', 'microphone']) {
    // The invariant is "this call adds or touches nothing". An entry may already exist: Windows writes one
    // (with LastUsedTimeStart/Stop) the first time an approved --allow-devices run opens a device, and the
    // test must not edit the registry to clear it. Any open here would change LastUsedTime*, so equality catches it.
    assert.ok(before0[cap].mine === after0[cap].mine, `${cap}: no new or changed entry for this host exe`);
    assert.ok(before0[cap].hostAny === after0[cap].hostAny, `${cap}: no ujwalam-host entry changed`);
  }
  const info = await c.call('host.info');
  assert.deepEqual(info.deviceModules, { 'win-dshow.dll': false, 'win-wasapi.dll': false }, 'still no device module');
  assert.equal(tasklistHas(h.child.pid, 'win-dshow.dll'), false);
});

test('project.plan without --allow-devices does not list devices: device layers say so', async () => {
  const place = { h: { visible: true, x: 0, y: 0, width: 640, height: 360 } };
  const doc = {
    version: 1, id: 'match-check', name: 'Match check', canvases: [{ id: 'h', width: 1280, height: 720, fps: 60 }],
    devices: [
      { id: 'dev-cam', kind: 'camera', name: '<camera>', match: { deviceId: '<device-id-1>' } },
      { id: 'dev-mic', kind: 'microphone', name: '<microphone>', match: { deviceId: '<device-id-2>' } }
    ],
    overlays: [], outputs: [],
    scenes: [{ id: 'main', name: 'Main', layers: [
      { id: 'cap', type: 'capture', name: 'A', source: { device: 'dev-cam' }, placements: place }
    ] }],
    audio: { tracks: [{ id: 't1', name: 'Track 1' }], sources: [
      { id: 'aud-mic', name: 'Mic', device: 'dev-mic', volumeDb: 0, muted: false, monitoring: 'off', tracks: ['t1'] }
    ] }
  };
  const snap0 = consentSnapshot();
  const plan = await planInHost(c, doc);
  const snap1 = consentSnapshot();
  for (const cap of ['webcam', 'microphone']) assert.ok(snap0[cap].mine === snap1[cap].mine, `${cap}: plan opened nothing`);
  assert.equal(plan.devicesListed, false);
  const by = Object.fromEntries(plan.unavailable.map((u) => [u.layer ?? `audio:${u.audio}`, u]));
  for (const k of ['cap', 'audio:aud-mic']) {
    assert.equal(by[k].code, 'forbidden');
    assert.equal(by[k].matchedBy, null);
    assert.match(by[k].reason, /devices were not listed/);
  }
  assert.deepEqual((await c.call('host.info')).deviceModules, { 'win-dshow.dll': false, 'win-wasapi.dll': false });
});

test('project v1: the validator refuses an invalid document before the host sees it', async () => {
  const bad = clone(SAMPLE);
  bad.scenes[0].layers[0].type = 'not-a-type';
  await assert.rejects(loadIntoHost(c, bad), (e) => e instanceof ProjectRefused && e.errors.length > 0);
  const bad2 = clone(SAMPLE);
  bad2.scenes[1].layers.push({ id: 'd1', type: 'duplicate', name: 'D', source: { layer: 'no-such-layer' }, placements: { h: { visible: true, x: 0, y: 0, width: 1, height: 1 } } });
  await assert.rejects(loadIntoHost(c, bad2), (e) => e instanceof ProjectRefused);
  assert.equal((await c.call('project.get')).format, 'ujwalam-host-test', 'host model unchanged');
  // and the host refuses a malformed document on its own (a direct caller that skipped the validator)
  const raw = clone(SAMPLE);
  raw.canvases = [{ id: 'x', width: 10, height: 10, fps: 60 }];
  assert.equal((await rpcErr('project.load', { project: raw })).code, -32602);
  assert.equal((await rpcErr('project.load', { project: SAMPLE, bases: { media: 'relative/dir' } })).code, -32602);
});

test('project v1 sample: plan lists device and browser layers as not buildable; skipUnavailable loads the rest on H and V', async () => {
  const bases = { media: media, overlays: media };
  const snap0 = consentSnapshot();
  const plan = await planInHost(c, SAMPLE, { bases });
  const snap1 = consentSnapshot();
  for (const cap of ['webcam', 'microphone']) assert.ok(snap0[cap].mine === snap1[cap].mine, `${cap}: plan opened nothing`);
  const un = Object.fromEntries(plan.unavailable.map((u) => [u.layer ?? `audio:${u.audio}`, u.code]));
  assert.equal(un['layer-game'], 'forbidden');
  assert.equal(un['layer-cam'], 'forbidden');
  assert.ok(['forbidden', 'unavailable'].includes(un['layer-chat']));
  assert.ok(un['audio:aud-mic'] && un['audio:aud-game'], 'device audio not buildable');
  for (const l of ['layer-bg', 'layer-logo', 'layer-intro', 'layer-title']) assert.equal(un[l], undefined, `${l} buildable`);
  assert.equal((await c.call('project.get')).format, 'ujwalam-host-test', 'plan changed nothing');

  assert.equal((await rpcErr('project.load', { project: SAMPLE, bases })).code, -32001, 'refused without skipUnavailable');
  const r = await loadIntoHost(c, SAMPLE, { bases, skipUnavailable: true });
  assert.deepEqual(r.built, { scenes: 2, sources: 4, items: 5, audio: 0, overlayLayers: 0, relay: null }, 'both audio entries are device audio (not built)');
  assert.equal(r.format, 'project-v1');
  const sc = await c.call('scenes.list');
  assert.deepEqual(sc.scenes.map((s) => `${s.canvas}:${s.id}:${s.active}`).sort(),
    ['H:scene-brb:false', 'H:scene-main:true', 'V:scene-brb:false', 'V:scene-main:true']);
  assert.equal((await rpcErr('layers.list', { scene: 'scene-main' })).code, -32602, 'scene on H and V: canvas required');
  const lh = await c.call('layers.list', { scene: 'scene-main', canvas: 'h' });
  assert.deepEqual(lh.layers.map((l) => l.id), ['layer-bg', 'layer-logo', 'layer-intro', 'layer-title']);
  const lv = await c.call('layers.list', { scene: 'scene-main', canvas: 'v' });
  assert.deepEqual(lv.layers.map((l) => l.id), ['layer-bg']);
  const logo = lh.layers.find((l) => l.id === 'layer-logo');
  assert.equal(logo.width, 64, 'image file loaded through the media base');
  assert.equal(lh.layers.find((l) => l.id === 'layer-intro').visible, false);
  const got = await c.call('project.get');
  assert.equal(got.format, 'project-v1');
  assert.equal(got.dirty, false);
  assert.equal(got.project.id, SAMPLE.id);
  await c.call('layers.setVisible', { scene: 'scene-main', layer: 'layer-bg', visible: false });
  const lv2 = await c.call('layers.list', { scene: 'scene-main', canvas: 'v' });
  assert.equal(lv2.layers[0].visible, false, 'no canvas: acts on both canvases');
  assert.equal((await c.call('project.get')).dirty, true);
});

// Pixel check of placements on H and V, a duplicate item, and one source shared by H, V and the duplicate.
const RENDER = {
  version: 1, id: 'render-check', name: 'Render check', activeScene: 'main',
  canvases: [{ id: 'h', width: 1280, height: 720, fps: 60 }, { id: 'v', width: 720, height: 1280, fps: 60 }],
  devices: [], overlays: [], outputs: [],
  scenes: [{
    id: 'main', name: 'Main', layers: [
      { id: 'bg', type: 'color', name: 'Bg', source: { color: '#ff0000' },
        placements: { h: { visible: true, x: 0, y: 0, width: 1280, height: 720 }, v: { visible: true, x: 0, y: 0, width: 720, height: 1280 } } },
      { id: 'box', type: 'color', name: 'Box', source: { color: '#00ff00' },
        placements: { h: { visible: true, x: 100, y: 100, width: 200, height: 200 }, v: { visible: true, x: 400, y: 900, width: 200, height: 200 } } },
      { id: 'box-dup', type: 'duplicate', name: 'Box again', source: { layer: 'box' },
        placements: { h: { visible: true, x: 900, y: 400, width: 200, height: 150 } } },
      { id: 'clip', type: 'media', name: 'Clip', source: { file: { base: 'media', rel: 'intro.mp4' }, loop: true },
        placements: { h: { visible: false, x: 0, y: 0, width: 320, height: 240 }, v: { visible: false, x: 0, y: 0, width: 320, height: 240 } } },
      { id: 'clip-dup', type: 'duplicate', name: 'Clip again', source: { layer: 'clip' },
        placements: { v: { visible: false, x: 0, y: 300, width: 320, height: 240 } } },
      { id: 'title', type: 'text', name: 'Title', source: { text: 'Test', size: 48, color: '#0000ff' },
        placements: { h: { visible: true, x: 500, y: 600, width: 300, height: 80 } } }
    ]
  }],
  audio: { tracks: [{ id: 't1', name: 'Track 1' }, { id: 't2', name: 'Track 2' }], sources: [
    { id: 'aud-clip', name: 'Clip audio', layer: 'clip', volumeDb: -6, muted: false, monitoring: 'off', tracks: ['t2'] }
  ] }
};

function frameRgb(file, w, h) {
  const r = spawnSync(process.env.FFMPEG || 'ffmpeg', ['-hide_banner', '-loglevel', 'error', '-ss', '0.8', '-i', file, '-frames:v', '1',
    '-f', 'rawvideo', '-pix_fmt', 'rgb24', '-'], { maxBuffer: 64 << 20, windowsHide: true });
  assert.equal(r.status, 0, String(r.stderr));
  assert.equal(r.stdout.length, w * h * 3);
  return (x, y) => { const i = (y * w + x) * 3; return [r.stdout[i], r.stdout[i + 1], r.stdout[i + 2]]; };
}

function near(px, rgb, what) {
  assert.ok(px.every((v, i) => Math.abs(v - rgb[i]) <= 48), `${what}: got ${px} want ${rgb}`);
}

test('project v1 render: H and V placements, duplicate item, shared source, layer audio', async () => {
  assert.ok((await import('../../../services/project/validate.mjs')).validateProject(RENDER).ok);
  const r = await loadIntoHost(c, RENDER, { bases: { media } });
  assert.deepEqual(r.unavailable, []);
  assert.deepEqual(r.built, { scenes: 1, sources: 4, items: 9, audio: 1, overlayLayers: 0, relay: null });
  const lh = await c.call('layers.list', { scene: 'main', canvas: 'H' });
  const dup = lh.layers.find((l) => l.id === 'box-dup');
  assert.equal(dup.duplicateOf, 'box');
  assert.equal(dup.source, 'box', 'duplicate shows the target source');
  const lv = await c.call('layers.list', { scene: 'main', canvas: 'V' });
  assert.equal(lv.layers.find((l) => l.id === 'clip-dup').source, 'clip');
  const mx = await c.call('mixer.list');
  const clips = mx.sources.filter((s) => s.audioSource === 'aud-clip');
  assert.equal(clips.length, 1, 'one mixer entry for a source shown by 3 items');
  assert.equal(mx.sources.length, 1, 'colour and text have no audio');
  assert.ok(Math.abs(clips[0].volumeDb + 6) < 0.01);
  assert.equal(clips[0].mixers, 2, 'track t2 is mixer bit 1');
  assert.equal(clips[0].name, 'Clip audio', 'mixer row named by the project audio source name');

  // inspector (P5a): partial placement patch merges into the project placement; bad patches change nothing
  const box0 = lh.layers.find((l) => l.id === 'box').placement;
  const sp = await c.call('layers.setPlacement', { scene: 'main', canvas: 'H', layer: 'box', placement: { x: 11, width: 222, crop: { left: 3 } } });
  assert.equal(sp.placement.x, 11);
  assert.equal(sp.placement.width, 222);
  assert.equal(sp.placement.y, box0.y, 'untouched fields kept');
  assert.equal(sp.placement.crop.left, 3);
  for (const bad of [{ width: 0 }, { opacity: 0.5 }, { crop: { left: -1 } }, {}]) {
    await assert.rejects(c.call('layers.setPlacement', { scene: 'main', canvas: 'H', layer: 'box', placement: bad }), JSON.stringify(bad));
  }
  const after = (await c.call('layers.list', { scene: 'main', canvas: 'H' })).layers.find((l) => l.id === 'box').placement;
  assert.deepEqual(after, sp.placement, 'a refused patch leaves the placement as it was');

  const RUNGS = [
    { id: 'rh', canvas: 'H', codec: 'h264', encoder: 'nvenc', rc: 'cbr', w: 640, h: 360, fps: 30, bitrate: 2500, gopSec: 1 },
    { id: 'rv', canvas: 'V', codec: 'h264', encoder: 'nvenc', rc: 'cbr', w: 360, h: 640, fps: 30, bitrate: 2500, gopSec: 1 }
  ];
  const sinks = [
    { id: 'fh', rung: 'rh', platform: 'local', proto: 'file', priority: 1, target: { transport: 'file', name: 'render-h.mkv' } },
    { id: 'fv', rung: 'rv', platform: 'local', proto: 'file', priority: 2, target: { transport: 'file', name: 'render-v.mkv' } }
  ];
  await c.call('outputs.configure', { rungs: RUNGS, audio: { bitrate: 128, sampleRate: 48000 }, sinks });
  await c.call('record.start', {});
  await new Promise((res) => setTimeout(res, 2000));
  await c.call('record.stop', {});
  let st;
  for (let i = 0; i < 60; i++) {
    st = await c.call('outputs.status');
    if (st.sinks.every((s) => s.state === 'stopped')) break;
    await new Promise((res) => setTimeout(res, 100));
  }
  const file = (id) => st.sinks.find((s) => s.id === id).path;
  const R = [255, 0, 0], G = [0, 255, 0];
  const ph = frameRgb(file('fh'), 640, 360); // H at 0.5 scale
  near(ph(100, 100), G, 'H box centre');
  near(ph(500, 237), G, 'H duplicate centre');
  near(ph(20, 20), R, 'H background');
  near(ph(200, 100), R, 'H right of box');
  near(ph(500, 180), R, 'H above duplicate');
  const pv = frameRgb(file('fv'), 360, 640); // V at 0.5 scale
  near(pv(250, 500), G, 'V box centre');
  near(pv(100, 100), R, 'V background');
  near(pv(250, 400), R, 'V above box');
  near(pv(500 / 2, 237), R, 'V: no duplicate (H-only placement)');
  await c.call('outputs.clear');
});

test('--project on the command line takes the host test format only (v1 goes through the validator)', async () => {
  await assert.rejects(
    launchHost({ dataDir: mkdtempSync(path.join(OUT, 'data-')), project: path.join(REPO_ROOT, 'tests', 'fixtures', 'project', 'sample.project.json') }),
    /exited with 3/);
});
